import {db} from './api.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function streakFor(rows,id){const dates=[...new Set(rows.map(r=>r.service_date))].sort().reverse();const served=new Set(rows.filter(r=>r.user_id===id).map(r=>r.service_date));let current=0,longest=0,run=0;for(const d of dates){run=served.has(d)?run+1:0;longest=Math.max(longest,run);}for(const d of dates){if(!served.has(d))break;current++;}return {current,longest,total:rows.filter(r=>r.user_id===id).length};}
export async function mountHistory(root,user){if(!root)return;root.innerHTML='<h1>History</h1><div class="workspace-loading" role="status"><span class="loading-ring"></span><span class="sr-only">Loading history</span></div>';const {data:rows,error}=await db.rpc('schedule_history');if(!root.isConnected)return;if(error){root.innerHTML='<h1>History</h1><p>Unable to load history. Please reopen this page.</p>';return;}const members=new Map(rows.filter(r=>r.user_id).map(r=>[r.user_id,r.full_name]));if(user.is_admin){const all=await db.from('profiles').select('id,full_name').eq('active',true);(all.data||[]).forEach(m=>members.set(m.id,m.full_name));}else{members.clear();members.set(user.id,user.full_name);}root.innerHTML=`<h1>History</h1><p class="small muted">Streaks count consecutive scheduled dates. Multiple assignments on one date count once.</p><div class="history-summary">${[...members].map(([id,name])=>{const s=streakFor(rows,id);return `<article class="panel"><strong>${esc(name)}</strong><p>${s.total} service assignments</p><small>Current streak: ${s.current} dates · Best: ${s.longest}</small></article>`;}).join('')}</div>${user.is_admin?'':`<div class="history-list">${rows.filter(r=>r.user_id===user.id&&r.position?.startsWith('cam_')).map(r=>`<section class="panel"><strong>${esc(r.service_date)}</strong><p>${esc(r.position.replace('cam_','Camera '))} · ${esc(r.service_name)}</p></section>`).join('')||'<p>No previous camera assignments.</p>'}</div>`}`;}

